59. /// A single entry in the cache.
60. #[derive(Clone)]
61. struct CacheEntry<V> {
62.     /// Cached value.
63.     value: V,
64.     /// Last-access counter (higher = more recently used).
65.     last_used: u64,
66. }
67. 
68. //==================================================================================================
69. // Cache Guard
70. //==================================================================================================
71. 
72. ///
73. /// # Description
74. ///
75. /// RAII guard providing a reference to a cached entry.
76. ///
77. /// Created by [`Cache::get()`]. Dereferences to `&V` for read access
78. /// and `&mut V` for write access. The LRU counter is bumped when the guard
79. /// is created.
80. ///
81. pub struct CacheGuard<'a, V> {
82.     /// Mutable reference to the cached value.
83.     value: &'a mut V,
84. }
85. 
86. impl<V> Deref for CacheGuard<'_, V> {
87.     type Target = V;
88. 
89.     fn deref(&self) -> &V {
90.         self.value
91.     }
92. }
93. 
94. impl<V> DerefMut for CacheGuard<'_, V> {
95.     fn deref_mut(&mut self) -> &mut V {
96.         self.value
97.     }
98. }
