 //! new one.
 //!
 //! # Example
 //!
 //! ```
 //! use cache::Cache;
 //!
 //! let mut cache: Cache<&str, i32> = Cache::new(2);
 //! cache.put("a", 1);
 //! cache.put("b", 2);
 //! assert_eq!(*cache.get(&"a").unwrap(), 1);
 //!
 //! // Inserting a third entry evicts "b" (least recently used).
 //! cache.put("c", 3);
 //! assert!(cache.get(&"b").is_none());
 //! assert_eq!(*cache.get(&"c").unwrap(), 3);
 //! ```

