         // If the key is already present, update in place.
         if let Some(entry) = self.entries.get_mut(&key) {
             self.counter += 1;
             entry.value = value;
             entry.last_used = self.counter;
             return;
         }

         // Evict the LRU entry if at capacity.
         if self.entries.len() >= self.capacity {
             self.evict();
